import{_ as a,o as i,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Diagnósticos y evidencia segura","description":"","frontmatter":{"title":"Diagnósticos y evidencia segura","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"89b9e0afb74a5046c1e4762cd97ac52f36bd019b9d24b5efc9c3f9d90cd353db","order":130},"headers":[],"relativePath":"es/developer/diagnostics.md","filePath":"es/developer/diagnostics.md","lastUpdated":1794611623000}'),n={name:"es/developer/diagnostics.md"};function t(r,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">Diagnósticos y evidencia segura <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to &quot;Diagnósticos y evidencia segura {#diagnostics-and-safe-evidence}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Recoge evidencia suficiente para localizar un fallo sin conservar secretos ni confundir diagnóstico con recuperación. Usa un host privado y conoce el <a href="./transports.html">transporte</a> seleccionado. La aplicación instala un único recolector por sesión; los componentes de estado llevan a él y no añaden entradas durante el renderizado.</p><h2 id="inspect-a-failure" tabindex="-1">Inspeccionar un fallo <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to &quot;Inspeccionar un fallo {#inspect-a-failure}&quot;">​</a></h2><ol><li>Abre la acción contextual del estado de la conexión, plugin, sincronización o actualizador afectado. El foco de teclado muestra la acción de registros igual que el cursor.</li><li>Filtra por origen, nivel y texto; inspecciona contexto y número de repeticiones.</li><li>Copia las entradas seleccionadas o filtradas que expliquen el problema. Revisa las exportaciones antes de compartirlas.</li><li>Compara la salud nativa con lo observado en el frontend:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>La comprobación de LIVE desconectado puede omitirse. Una capacidad compilada no demuestra disponibilidad real. En escritorio el panel no es modal; las pantallas estrechas usan <code>/debug</code> con destino de regreso. La exportación nativa utiliza <code>system.saveFile</code>; el navegador descarga localmente.</p><h2 id="understand-retention" tabindex="-1">Entender la retención <a class="header-anchor" href="#understand-retention" aria-label="Permalink to &quot;Entender la retención {#understand-retention}&quot;">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> limita el historial a 2.000 entradas y 2 MiB de UTF-8 serializado. Eventos consecutivos iguales de un origen/entidad en cinco segundos se combinan con un contador. La ocultación ocurre antes de retener datos e incluye credenciales reconocibles y secretos de URL; no siempre detecta valores arbitrarios sin etiqueta de terceros. No añadas ajustes completos, cookies, parámetros RPC ni cuerpos HTTP al recolector.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El visor ofrece historial acotado de sesión y navegación contextual, no auditoría duradera. Recargar o desmontar libera la memoria. Borrar el historial no elimina el error de conexión ni repara su causa. Los identificadores de solicitud Cloud ayudan a correlacionar sobres seguros; la cobertura depende de los recolectores instalados y no garantiza capturar todo error nativo o de registro.</p><h2 id="verify-and-recover" tabindex="-1">Verificación y recuperación <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;Verificación y recuperación {#verify-and-recover}&quot;">​</a></h2><p>Ejecuta <code>bun scripts/task.ts test web diagnostics</code> y consulta el <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">código del recolector</a>. Reproduce ocultación, descarte y repeticiones con valores sintéticos. Ante conflictos, órdenes inciertas o credenciales vencidas, vuelve al flujo propietario de recuperación. Copiar un diagnóstico recoge evidencia; nunca repite acciones ni aprueba confianza nueva.</p>`,13)])])}const g=a(n,[["render",t]]);export{h as __pageData,g as default};
